import {setAppearance} from './world.js';
const $=id=>document.getElementById(id);
export const milestones=[{coins:3,title:'Gold pendant',type:'pendant',metal:'#d4a742',description:'Your first emblem, carried close.'},{coins:6,title:'Platinum-look pendant',type:'pendant',metal:'#c4d4dc',description:'A cooler finish for a longer journey.'},{coins:9,title:'Island trophy',type:'trophy',metal:'#d4a742',description:'A little monument to your adventure.'},{coins:12,title:'Woven journey rug',type:'rug',description:'Bring the island into your room.'}];
export let appearance={name:'Explorer',coat:'#28645c',skin:'#f2c994',scarf:'#d59b36',pattern:'stars',hat:'hood'};
export let rug={palette:'lagoon',tiles:Array(9).fill(0),solved:false};
const palettes={lagoon:['#e9dfba','#317f89','#dbad54'],sunset:['#f5dfc5','#b15e56','#e0a143'],alpine:['#e7e9df','#4b6d65','#88a3b5']};
let selectedProduct='scarf', callbacks, selectedTile=0;
const safeText=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const glyph=emblem=>({sun:'☀',moon:'☾',mountain:'▲'})[emblem]||'☀';
function character(){const a=appearance;return `<g transform="translate(110 33)"><ellipse cx="70" cy="165" rx="43" ry="9" fill="#213e3120"/><path d="M45 120h22v39H43zm29 0h22l3 39H76" fill="#594638"/><rect x="35" y="64" width="72" height="75" rx="26" fill="${a.coat}"/><rect x="24" y="80" width="20" height="50" rx="9" fill="${a.coat}"/><rect x="99" y="80" width="20" height="50" rx="9" fill="${a.coat}"/><circle cx="71" cy="42" r="29" fill="${a.skin}"/><circle cx="62" cy="43" r="2.5" fill="#263c31"/><circle cx="82" cy="43" r="2.5" fill="#263c31"/><path d="M66 56q6 5 12 0" fill="none" stroke="#6f4a32" stroke-width="2"/>${a.hat==='none'?'':a.hat==='cap'?`<path d="M39 33q0-39 63 0z" fill="${a.coat}"/><rect x="37" y="29" width="78" height="8" rx="4" fill="${a.coat}"/>`:`<path d="M35 31L70-14l37 45q-38-15-72 0" fill="${a.coat}"/>`}<rect x="37" y="67" width="69" height="18" rx="8" fill="url(#fabric)"/><path d="M88 77h17v56l-8-7-9 7z" fill="url(#fabric)"/></g>`}
function fabric(){const a=appearance;const decoration=a.pattern==='stripes'?'<path d="M-10 0l40 40M10-10l40 40" stroke="#fff0c8" stroke-width="5"/>':a.pattern==='waves'?'<path d="M-5 10q10-8 20 0t20 0M-5 30q10-8 20 0t20 0" fill="none" stroke="#fff0c8" stroke-width="3"/>':'<path d="M20 5l4 10 10 5-10 4-4 10-4-10-10-4 10-5z" fill="#fff0c8"/>';return `<defs><pattern id="fabric" width="40" height="40" patternUnits="userSpaceOnUse"><rect width="40" height="40" fill="${a.scarf}"/>${decoration}</pattern></defs>`}
export function rugSvg(){const colors=palettes[rug.palette];return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 230" role="img" aria-label="Your woven rug design"><rect width="300" height="230" fill="#e8e5d9"/><ellipse cx="150" cy="206" rx="104" ry="8" fill="#213e3118"/><g transform="translate(53 20)">${rug.tiles.map((n,i)=>`<g transform="translate(${i%3*64} ${Math.floor(i/3)*64})"><rect width="64" height="64" fill="${colors[i%3]}"/><g transform="rotate(${n*90} 32 32)"><path d="M0 64L32 9l32 55z" fill="${colors[(i+1)%3]}" opacity=".8"/><path d="M0 64L32 32l32 32z" fill="${colors[(i+2)%3]}" opacity=".75"/></g></g>`).join('')}<rect width="192" height="192" fill="none" stroke="${colors[0]}" stroke-width="5"/>${Array.from({length:25},(_,i)=>`<path d="M${i*8} 192v9M${i*8} 0v-9" stroke="${colors[0]}" stroke-width="3"/>`).join('')}</g></svg>`}
export function productSvg(type,emblem='sun',metal='#d4a742'){if(type==='rug')return rugSvg();const content=type==='avatar'?character():type==='pillow'?`<path d="M62 35Q150 18 240 35Q256 112 238 198Q150 213 62 198Q46 118 62 35" fill="#f4ede0" stroke="#ddd1b9" stroke-width="3"/><g transform="translate(18 20) scale(.8)">${character()}</g>`:type==='scarf'?'<path d="M35 45L246 25l18 148-211 25z" fill="url(#fabric)" stroke="#f6e6b2" stroke-width="4"/><path d="M62 193l193-27" stroke="#213e3125" stroke-width="3"/>':type==='trophy'?`<rect x="100" y="171" width="100" height="28" rx="5" fill="#31493c"/><path d="M130 178l8-65h24l8 65" fill="${metal}"/><circle cx="150" cy="77" r="48" fill="${metal}" stroke="#9f7a32" stroke-width="4"/><text x="150" y="94" text-anchor="middle" font-size="47" fill="#6f5425">${glyph(emblem)}</text>`:`<path d="M77-20Q150 142 223-20" fill="none" stroke="${metal}" stroke-width="4"/><circle cx="150" cy="134" r="48" fill="${metal}" stroke="#8c7748" stroke-width="3"/><circle cx="150" cy="134" r="40" fill="none" stroke="#fff0c7" stroke-width="2"/><text x="150" y="151" text-anchor="middle" font-size="48" fill="#6f623b">${glyph(emblem)}</text>`;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 230" role="img" aria-label="${type} design concept">${fabric()}<rect width="300" height="230" fill="#ece7d7"/>${content}</svg>`.replaceAll('id="fabric"','id="fabric-'+type+'"').replaceAll('url(#fabric)','url(#fabric-'+type+')')}
function prompt(){const a=appearance;if(selectedProduct==='rug')return `Hand tufted wool rug with a 3 by 3 alpine geometric pattern, ${rug.palette} palette (${palettes[rug.palette].join(', ')}), repeating upright mountain peaks. Keep the exact layout from the attached design preview.`;if(selectedProduct==='scarf')return `Silk scarf with ${a.pattern} pattern in ${a.scarf} and warm cream #fff0c8, inspired by ${a.name}'s island adventure. Match the attached scarf design preview.`;return `Square pillow cover illustrated with ${a.name}, a friendly explorer with ${a.skin} skin, ${a.coat} coat, ${a.hat==='none'?'no hat':a.hat}, and ${a.scarf} ${a.pattern} scarf, on a cream background. Match the attached character preview.`}
function refreshAppearance(){setAppearance(appearance);$('avatar-preview').innerHTML=productSvg('avatar');$('studio-preview').innerHTML=productSvg(selectedProduct);$('design-brief').value=prompt();$('character-name').textContent=appearance.name+"’s keepsakes";document.querySelectorAll('[data-choice]').forEach(b=>b.classList.toggle('selected',appearance[b.dataset.choice]===b.dataset.value))}
function open(id){callbacks.pause();$(id).showModal()}
function close(id){$(id).close();callbacks.resume()}
function drawTrail(){const info=callbacks.info(),next=milestones.find(m=>m.coins>info.collected)||milestones.at(-1);$('next-reward').innerHTML=`<span>${glyph(info.emblem)}</span><span><small>${info.collected>=12?'COLLECTION COMPLETE':'NEXT KEEPSAKE · '+next.coins+' COINS'}</small><strong>${next.title}</strong></span><b>›</b>`;$('trail-list').innerHTML=milestones.map(m=>`<div class="trail-card ${info.collected>=m.coins?'unlocked':''}"><div class="mini-product">${productSvg(m.type,info.emblem,m.metal)}</div><div><small>${info.collected>=m.coins?'UNLOCKED':m.coins+' COINS'}</small><strong>${m.title}</strong><p>${m.description}</p></div><span>${info.collected>=m.coins?'✓':'♢'}</span></div>`).join('')}
export function updateTrail(){if(callbacks)drawTrail()}
export function initKeepsakes(c){callbacks=c;document.body.insertAdjacentHTML('beforeend',`
<dialog id="wardrobe-dialog"><div class="sheet"><div class="sheet-heading"><span class="eyebrow">MAKE THE EXPLORER YOURS</span><button data-close="wardrobe-dialog" class="close" aria-label="Close customization">×</button></div><h2>Your adventure.<br>Your character.</h2><div id="avatar-preview" class="product-preview avatar-preview"></div><label class="form-label">Explorer name<input id="explorer-name" maxlength="24" value="Explorer"></label><fieldset><legend>Coat color</legend><div class="swatches">${['#28645c','#536ca4','#a45150','#70548b','#ce9740'].map(v=>`<button data-choice="coat" data-value="${v}" style="--swatch:${v}" aria-label="Coat ${v}"></button>`).join('')}</div></fieldset><fieldset><legend>Skin tone</legend><div class="swatches">${['#f2c994','#c88e66','#8e5e42','#5d3c2d'].map(v=>`<button data-choice="skin" data-value="${v}" style="--swatch:${v}" aria-label="Skin ${v}"></button>`).join('')}</div></fieldset><fieldset><legend>Headwear</legend><div class="choice-row">${['hood','cap','none'].map(v=>`<button data-choice="hat" data-value="${v}">${v}</button>`).join('')}</div></fieldset><fieldset><legend>Your signature scarf</legend><div class="swatches">${['#d59b36','#487f9e','#b05a69','#6c8b54'].map(v=>`<button data-choice="scarf" data-value="${v}" style="--swatch:${v}" aria-label="Scarf ${v}"></button>`).join('')}</div><div class="choice-row">${['stars','stripes','waves'].map(v=>`<button data-choice="pattern" data-value="${v}">${v}</button>`).join('')}</div></fieldset><button id="wear-outfit" class="primary">Wear it on the island</button><button id="outfit-products" class="secondary">See my scarf & character pillow</button></div></dialog>
<dialog id="trail-dialog"><div class="sheet"><div class="sheet-heading"><span class="eyebrow">THE KEEPSAKE TRAIL</span><button data-close="trail-dialog" class="close" aria-label="Close reward trail">×</button></div><h2>Keep going.<br>Bring more home.</h2><p>Coins unlock designs. Physical products would be purchased separately after an Arcade quote.</p><div id="trail-list"></div><button id="trail-studio" class="primary">My character’s keepsakes</button><p class="caption">Concept previews. Platinum materials and trophies require availability confirmation.</p></div></dialog>
<dialog id="studio-dialog"><div class="sheet"><div class="sheet-heading"><span class="eyebrow">FROM ISLAND TO EVERYDAY</span><button data-close="studio-dialog" class="close" aria-label="Close design studio">×</button></div><h2 id="character-name">Explorer’s keepsakes</h2><div class="choice-row product-tabs"><button data-product="scarf">Scarf</button><button data-product="pillow">Character pillow</button><button data-product="rug">Journey rug</button></div><div id="studio-preview" class="product-preview"></div><p id="studio-description">Your scarf, with the exact colors and pattern you wear in the game.</p><label class="form-label">Your product design brief<textarea id="design-brief" readonly rows="4"></textarea></label><button id="download-design" class="primary">Save design reference</button><button id="copy-design" class="secondary">Copy design brief for Arcade</button><p class="caption" id="studio-status" role="status">Design concept. Arcade generation and pricing are not connected yet.</p><p class="caption">A character pillow is the current textile concept. A plush toy would need a supported maker.</p></div></dialog>
<dialog id="loom-dialog"><div class="sheet"><div class="sheet-heading"><span class="eyebrow">THE WEAVER’S CLEARING</span><button data-close="loom-dialog" class="close" aria-label="Leave weaving puzzle">×</button></div><h2>Restore the pattern.<br>Make it yours.</h2><p>Rotate each tile until all nine peaks point up. Choose a palette, and the repaired weaving becomes your rug.</p><div class="choice-row">${Object.keys(palettes).map(v=>`<button data-palette="${v}">${v}</button>`).join('')}</div><div id="weave-grid" aria-label="Rug tile puzzle"></div><p id="weave-feedback" role="status">Tap a tile to rotate its peak.</p><button id="finish-weave" class="primary" disabled>Finish the weaving</button><button id="view-woven-rug" class="secondary" hidden>See my rug design</button></div></dialog>`);
$('wardrobe').onclick=()=>open('wardrobe-dialog');$('collection').onclick=()=>{drawTrail();open('trail-dialog')};$('next-reward').onclick=$('collection').onclick;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>close(b.dataset.close));for(const id of ['wardrobe-dialog','trail-dialog','studio-dialog','loom-dialog'])$(id).addEventListener('cancel',e=>{e.preventDefault();close(id)});
document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{appearance[b.dataset.choice]=b.dataset.value;refreshAppearance()});$('explorer-name').oninput=e=>{appearance.name=e.target.value.trim()||'Explorer';refreshAppearance()};$('wear-outfit').onclick=()=>close('wardrobe-dialog');$('outfit-products').onclick=()=>{$('wardrobe-dialog').close();openStudio('scarf')};$('trail-studio').onclick=()=>{$('trail-dialog').close();openStudio('pillow')};document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>openStudio(b.dataset.product));$('copy-design').onclick=async()=>{try{await navigator.clipboard.writeText(prompt());$('studio-status').textContent='Design brief copied. Bring it and the reference to Arcade.'}catch{$('studio-status').textContent='Select the design brief above to copy it.'}};$('download-design').onclick=()=>{const blob=new Blob([productSvg(selectedProduct)],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='relic-island-'+selectedProduct+'.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('studio-status').textContent='Design reference saved. Arcade pricing is still pending.'};
document.querySelectorAll('[data-palette]').forEach(b=>b.onclick=()=>{rug.palette=b.dataset.palette;renderWeave()});$('finish-weave').onclick=()=>{rug.solved=true;callbacks.woven();$('weave-feedback').textContent='Pattern restored. You designed a real-world rug concept.';$('finish-weave').hidden=true;$('view-woven-rug').hidden=false};$('view-woven-rug').onclick=()=>{$('loom-dialog').close();openStudio('rug')};refreshAppearance();drawTrail();}
export function openStudio(type='scarf'){selectedProduct=type;refreshAppearance();document.querySelectorAll('[data-product]').forEach(b=>b.classList.toggle('selected',b.dataset.product===type));$('studio-status').textContent='Design concept. Arcade generation and pricing are not connected yet.';$('studio-description').textContent=type==='scarf'?'The same colors and pattern your explorer wears, imagined as a silk scarf.':type==='pillow'?'Your customized explorer, illustrated on a pillow cover.':'The pattern you restored at the loom, imagined as a hand tufted rug.';if(!$('studio-dialog').open)open('studio-dialog')}
function renderWeave(){const colors=palettes[rug.palette];$('weave-grid').innerHTML=rug.tiles.map((n,i)=>`<button data-tile="${i}" aria-label="Rotate tile ${i+1}, currently ${['up','right','down','left'][n]}" style="background:${colors[i%3]}"><span style="transform:rotate(${n*90}deg);color:${colors[(i+1)%3]}">▲</span></button>`).join('');document.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{rug.tiles[Number(b.dataset.tile)]=(rug.tiles[Number(b.dataset.tile)]+1)%4;renderWeave()});$('finish-weave').disabled=!rug.tiles.every(n=>n===0);document.querySelectorAll('[data-palette]').forEach(b=>b.classList.toggle('selected',b.dataset.palette===rug.palette));}
export function openLoom(){if(!rug.solved&&rug.tiles.every(n=>n===0))rug.tiles=[1,0,3,0,2,0,3,0,1];renderWeave();$('finish-weave').hidden=rug.solved;$('view-woven-rug').hidden=!rug.solved;open('loom-dialog')}
